<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserFederatedIdentityUserAccessor
{
    private UserFederatedIdentityUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserFederatedIdentityUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserFederatedIdentityUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserFederatedIdentityUserVO::from($user);
        return $copy;
    }
}
